In the Observer design pattern implementation below, what will be the output?

class Publisher {
    private String message = "";
    private Subscriber subscriber;
    public void setSubscriber(Subscriber s) { this.subscriber = s; }
    public void notifySubscriber() {
        if (subscriber != null) subscriber.update(message);
    }
    public void setMessage(String msg) {
        this.message = msg;
        notifySubscriber();
    }
}
class Subscriber {
    public void update(String message) {
        System.out.println("Received: " + message);
    }
}
public class Main {
    public static void main(String[] args) {
        Publisher pub = new Publisher();
        Subscriber sub = new Subscriber();
        pub.setSubscriber(sub);
        pub.setMessage("Hello");
    }
}

